insert into public.articles (id,title,slug,excerpt,content,category,author,image,image_alt,published_at,is_published) values ($q$news-1$q$,$q$HIMA TL UNTAN Tanam 1000 Pohon di Kawasan Mangrove Mempawah$q$,$q$hima-tl-untan-tanam-1000-pohon-2025$q$,$q$Kegiatan penanaman 1000 pohon mangrove berhasil dilaksanakan sebagai bentuk kepedulian terhadap ekosistem pesisir Kalimantan Barat.$q$,$q$<p>Pontianak — Himpunan Mahasiswa Teknik Lingkungan Universitas Tanjungpura (HIMA TL UNTAN) berhasil melaksanakan kegiatan penanaman 1000 pohon mangrove di kawasan pesisir Mempawah, Kalimantan Barat.</p>
insert into public.articles (id,title,slug,excerpt,content,category,author,image,image_alt,published_at,is_published) values ($q$news-2$q$,$q$Seminar Nasional: Teknologi Pengolahan Air Limbah Berkelanjutan$q$,$q$seminar-nasional-teknologi-air-limbah-2025$q$,$q$HIMA TL UNTAN menyelenggarakan seminar nasional dengan pembicara dari Kementerian LHK dan akademisi terkemuka.$q$,$q$<p>Departemen Pendidikan HIMA TL UNTAN sukses menyelenggarakan Seminar Nasional bertema "Inovasi Teknologi Pengolahan Air Limbah untuk Pembangunan Berkelanjutan".</p>
insert into public.articles (id,title,slug,excerpt,content,category,author,image,image_alt,published_at,is_published) values ($q$news-3$q$,$q$Pembukaan Pre-Order Hoodie Green Engineering Batch 2$q$,$q$pre-order-hoodie-green-engineering-batch-2$q$,$q$Kabar gembira! Hoodie Green Engineering batch 2 resmi dibuka. Segera pesan sebelum kuota habis.$q$,$q$<p>Departemen Kewirausahaan HIMA TL UNTAN membuka pre-order Hoodie Green Engineering Batch 2. Hoodie ini hadir dengan desain baru yang lebih fresh namun tetap mempertahankan identitas Teknik Lingkungan.</p>
insert into public.articles (id,title,slug,excerpt,content,category,author,image,image_alt,published_at,is_published) values ($q$news-4$q$,$q$HIMA TL UNTAN Raih Juara 1 Kompetisi Paper Lingkungan Se-Kalimantan$q$,$q$juara-1-kompetisi-paper-lingkungan$q$,$q$Delegasi HIMA TL UNTAN berhasil meraih juara pertama dalam kompetisi paper ilmiah tingkat regional.$q$,$q$<p>Tim delegasi dari HIMA TL UNTAN berhasil membawa pulang trophy juara 1 dalam Kompetisi Paper Ilmiah Lingkungan Se-Kalimantan yang diselenggarakan di Universitas Lambung Mangkurat, Banjarmasin.</p>
